// Stratified sample: N resolved tickets per engineer per week - swap for helpdesk API random sample
return [{ json: { tickets: [
  { engineer: 'Dana', ticketId: 'T-4001', customerMsg: 'Our workflow stopped running overnight and we have a launch today, please help', reply: 'Hi! I can see the execution failed on an expired credential at 2am. I have re-authenticated the connection and re-run the workflow successfully just now. To prevent this, I also enabled the credential expiry warning. Anything else before your launch? Good luck today!' },
  { engineer: 'Marco', ticketId: 'T-4002', customerMsg: 'How do I export my execution history?', reply: 'Settings > Executions > Export.' },
  { engineer: 'Priya', ticketId: 'T-4003', customerMsg: 'Getting a 429 error on the HTTP node since yesterday', reply: 'That is a rate limit from the API you are calling, not from us. Add a Loop with a Wait node between batches, or check if your plan with that provider allows a higher rate. Here is our doc on handling rate limits: [link]. Want me to look at your workflow together?' }
] } }];

const raw = $input.first().json.output ?? '';
const match = String(raw).match(/\{[\s\S]*\}/);
let reviews = [];
try { reviews = JSON.parse(match ? match[0] : raw).reviews || []; } catch (e) { reviews = []; }
let body = 'Weekly ticket QA (LEAD ONLY, feeds 1:1s, never the channel):\n';
for (const r of reviews) {
  const avg = ((r.empathy + r.accuracy + r.completeness + r.nextStep) / 4).toFixed(1);
  body += '\n' + r.engineer + ' - ' + r.ticketId + ' - avg ' + avg + '/5 (E' + r.empathy + ' A' + r.accuracy + ' C' + r.completeness + ' N' + r.nextStep + ')\n  ' + r.coachingNote + '\n';
}
body += '\nCalibration rule: QA scores are coaching material. If a score surprises you, read the ticket before the 1:1, not during it.';
return [{ json: { subject: 'Ticket QA: ' + reviews.length + ' reviews ready for 1:1s', body } }];
